package app.kinnect.audit;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;import java.io.*;
public class StoreLayoutAudit extends Instrumentation {
  private Object call(Activity a,String name)throws Exception{Method m=a.getClass().getDeclaredMethod(name);m.setAccessible(true);return m.invoke(a);}
  private TextView find(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().equals(text))return(TextView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){TextView t=find(((ViewGroup)v).getChildAt(i),text);if(t!=null)return t;}return null;}
  private void check(boolean value,String message){if(!value)throw new AssertionError(message);}
  private void checkNoOverlap(View v){if(v instanceof LinearLayout){LinearLayout l=(LinearLayout)v;if(l.getOrientation()==LinearLayout.VERTICAL){int bottom=-1;for(int i=0;i<l.getChildCount();i++){View child=l.getChildAt(i);if(child.getVisibility()!=View.VISIBLE)continue;check(child.getTop()>=bottom,"Overlapping vertical store items");bottom=child.getBottom();}}}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)checkNoOverlap(((ViewGroup)v).getChildAt(i));}
  public void onCreate(Bundle b){super.onCreate(b);start();}
  public void onStart(){Bundle out=new Bundle();try{
    Activity a=startActivitySync(new Intent().setClassName("app.kinnect.live","app.kinnect.live.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1400);
    runOnMainSync(()->{try{call(a,"intro");}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();
    runOnMainSync(()->{TextView t=find(a.getWindow().getDecorView(),"VI / EN");check(t!=null,"Missing language selector");check(t.getLineCount()==1,"Language wraps");check(t.getLayout().getEllipsisCount(0)==0,"Language clipped");check(t.getGravity()==android.view.Gravity.CENTER,"Language not centered");ViewGroup p=(ViewGroup)t.getParent();check(!((LinearLayout)p).isBaselineAligned(),"Brand row shifts text baseline");check(Math.abs(t.getTop()+t.getHeight()/2f-p.getHeight()/2f)<=2,"Language vertically offset");check(t.getRight()<=p.getWidth(),"Language overflows row");});
    try(FileOutputStream f=new FileOutputStream(new File(a.getExternalFilesDir(null),"layout-language.jpg"))){getUiAutomation().takeScreenshot().compress(android.graphics.Bitmap.CompressFormat.JPEG,95,f);}
    runOnMainSync(()->{try{
      Class<?> c=a.getClassLoader().loadClass("app.kinnect.live.NativeCalls");Constructor<?> constructor=c.getDeclaredConstructor(Activity.class,String.class);constructor.setAccessible(true);Object calls=constructor.newInstance(a,"https://app.kinnect.io.vn");Field mode=c.getDeclaredField("mode");mode.setAccessible(true);mode.set(calls,"audio");Method open=c.getDeclaredMethod("open",org.json.JSONObject.class);open.setAccessible(true);open.invoke(calls,new org.json.JSONObject().put("name","Navigation QA"));Method minimize=c.getDeclaredMethod("minimize");minimize.setAccessible(true);minimize.invoke(calls);Field dialog=c.getDeclaredField("dialog");dialog.setAccessible(true);check(dialog.get(calls)!=null,"Minimize ended call");check(!((Dialog)dialog.get(calls)).isShowing(),"Minimize did not hide dialog");Method attach=c.getDeclaredMethod("attachReturn",ViewGroup.class);attach.setAccessible(true);LinearLayout other=new LinearLayout(a);attach.invoke(calls,other);check(other.getChildCount()==1,"No return banner after navigation");check(dialog.get(calls)!=null,"Navigation ended call");other.getChildAt(0).performClick();check(((Dialog)dialog.get(calls)).isShowing(),"Could not return to call");Method close=c.getDeclaredMethod("close");close.setAccessible(true);close.invoke(calls);
    }catch(Exception e){throw new RuntimeException(e);}});
    runOnMainSync(()->a.finish());
    Activity live=startActivitySync(new Intent().setClassName("app.kinnect.live","app.kinnect.live.LiveActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(600);
    runOnMainSync(()->{try{
      Field ready=live.getClass().getDeclaredField("ready");ready.setAccessible(true);ready.setBoolean(live,true);call(live,"renderRooms");
      Field rooms=live.getClass().getDeclaredField("rooms");rooms.setAccessible(true);LinearLayout container=(LinearLayout)rooms.get(live);check(container.getGravity()==Gravity.CENTER,"Live empty state not centered");
      TextView badge=(TextView)call(live,"previewBadge");int width=Math.round(180*live.getResources().getDisplayMetrics().density);badge.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));check(badge.getMeasuredWidth()==width,"Preview badge width");check(badge.getLayout().getHeight()+badge.getPaddingTop()+badge.getPaddingBottom()<=badge.getMeasuredHeight(),"Preview text clipped");
      for(int line=0;line<badge.getLayout().getLineCount();line++)check(badge.getLayout().getLineWidth(line)<=width-badge.getPaddingLeft()-badge.getPaddingRight()+1,"Preview text overflows");
    }catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();
    runOnMainSync(()->{try{Field config=live.getClass().getDeclaredField("config");config.setAccessible(true);config.set(live,new org.json.JSONObject().put("iceServers",new org.json.JSONArray()));Method show=live.getClass().getDeclaredMethod("showRoom",org.json.JSONObject.class);show.setAccessible(true);show.invoke(live,new org.json.JSONObject().put("room",new org.json.JSONObject().put("id","layout-only").put("host","Minh Anh").put("title","Cùng trò chuyện tối nay")));Method event=live.getClass().getMethod("event",org.json.JSONObject.class);event.invoke(live,new org.json.JSONObject().put("type","count").put("viewers",2).put("users",new org.json.JSONArray("[{\"id\":\"one\",\"name\":\"Linh\"},{\"id\":\"two\",\"name\":\"Nam\"}]")));event.invoke(live,new org.json.JSONObject().put("type","viewer-joined").put("user",new org.json.JSONObject().put("name","Linh")));}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();
    try(FileOutputStream f=new FileOutputStream(new File(live.getExternalFilesDir(null),"live-redesign.jpg"))){getUiAutomation().takeScreenshot().compress(android.graphics.Bitmap.CompressFormat.JPEG,95,f);}
    runOnMainSync(()->live.finish());
    Activity store=startActivitySync(new Intent().setClassName("app.kinnect.live","app.kinnect.live.StoreActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(900);
    runOnMainSync(()->{try{Field catalog=store.getClass().getDeclaredField("catalog");catalog.setAccessible(true);catalog.set(store,new org.json.JSONObject("{\"products\":[{\"id\":\"kinnect_style_aurora\",\"kind\":\"style\",\"name\":\"Aurora\",\"description\":\"Khung ảnh tím hồng\",\"colors\":[\"#8b5cf6\",\"#ec4899\"],\"referenceVnd\":29000}],\"owned\":[],\"billingReady\":false}"));call(store,"draw");check(store.getResources().getIdentifier("ic_web_shopping_bag","drawable",store.getPackageName())!=0,"Missing store icon");check(store.getResources().getIdentifier("ic_web_gift","drawable",store.getPackageName())!=0,"Missing gift icon");}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();
    Thread.sleep(500);waitForIdleSync();runOnMainSync(()->{ViewGroup decor=(ViewGroup)store.getWindow().getDecorView();check(find(decor,"Ví Kinnect")==null,"Wallet still nested inside store");checkNoOverlap(decor);check(find(decor,"Kinnect")!=null,"Missing brand header");check(find(decor,"Video")!=null,"Missing bottom navigation");});try(FileOutputStream f=new FileOutputStream(new File(store.getExternalFilesDir(null),"shop-redesign.jpg"))){getUiAutomation().takeScreenshot().compress(android.graphics.Bitmap.CompressFormat.JPEG,95,f);}
    runOnMainSync(()->store.finish());out.putString("result","PASS: VI/EN centered and contained; empty Live centered; preview badge wraps without clipping");finish(Activity.RESULT_OK,out);
  }catch(Throwable e){out.putString("error",e.toString());finish(Activity.RESULT_CANCELED,out);}}
}
